import{_ as r,o as t,c as n,ag as s}from"./chunks/framework.D5hoimZQ.js";const q=JSON.parse('{"title":"🔬 科学快报 | 2026年8月27日（第 ? 期 · 事后重建版）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/reconstructed/2026-08-27.md","filePath":"science-log/src/reconstructed/2026-08-27.md"}'),e={name:"science-log/src/reconstructed/2026-08-27.md"};function a(g,o,i,u,c,l){return t(),n("div",null,[...o[0]||(o[0]=[s('<h1 id="🔬-科学快报-2026年8月27日-第-期-·-事后重建版" tabindex="-1">🔬 科学快报 | 2026年8月27日（第 ? 期 · 事后重建版） <a class="header-anchor" href="#🔬-科学快报-2026年8月27日-第-期-·-事后重建版" aria-label="Permalink to &quot;🔬 科学快报 | 2026年8月27日（第 ? 期 · 事后重建版）&quot;">​</a></h1><blockquote><p>⚠️ <strong>事后重建版</strong>：本文件<strong>不是</strong>当日发布原文。由 2026-11-05 依 arXiv / CrossRef <strong>按发布日期回溯检索</strong>生成，选题与排序均为事后判定，<strong>不代表历史原貌</strong>。 说明：2026-08-27 为<strong>周四</strong>。CrossRef 当日命中：Nature（0028-0836）仅 8 条且<strong>全部为 <code>10.1038/d41586-…</code> 新闻 / Daily briefing</strong>，<strong>无一条 <code>s41586</code> 研究论文</strong>（该刊本周研究论文的 <code>published</code> 落在 08-25 / 08-26），故本日科学版<strong>不取 Nature</strong>；Science 系（10.1126）当日命中 <strong>46 条</strong>（含 <code>z…</code> 新闻稿与社论，已剔除），研究论文充足；PNAS（0027-8424）当日命中 <strong>10 条</strong>研究论文。<strong>科学 5 篇</strong>取自 Science / PNAS 当日（<code>published</code> = 2026-08-27）研究论文；<strong>AI 5 篇</strong>取自当日 arXiv cs.AI 提交（<code>submittedDate [202608270000 TO 202608272359]</code> 命中 30 篇，恰好触及 <code>max_results</code> 上限）。期号因当日原本无刊期，标为 <code>（第 ? 期 · 事后重建版）</code>。 取证：CrossRef（Nature 0028-0836 / Science 10.1126 / PNAS 0027-8424）+ arXiv 日期区间 ｜ 重建日：2026-11-05</p></blockquote><h2 id="🔬-科学前沿" tabindex="-1">🔬 科学前沿 <a class="header-anchor" href="#🔬-科学前沿" aria-label="Permalink to &quot;🔬 科学前沿&quot;">​</a></h2><h3 id="🧬-用深度学习从头设计-rna-假结-生成式-ai-在盲测中追平人类专家" tabindex="-1">🧬 用深度学习从头设计 RNA 假结：生成式 AI 在盲测中追平人类专家 <a class="header-anchor" href="#🧬-用深度学习从头设计-rna-假结-生成式-ai-在盲测中追平人类专家" aria-label="Permalink to &quot;🧬 用深度学习从头设计 RNA 假结：生成式 AI 在盲测中追平人类专家&quot;">​</a></h3><p><strong>De novo design of RNA pseudoknots with deep learning</strong><em>Science（2026）</em></p><p>RNA 设计长期受限于三维结构预测精度。本文转向<strong>假结（pseudoknot）二级结构</strong>这一足够复杂、又可用现有工具可靠判定的目标，证明<strong>复杂 RNA 结构可以被从头设计出来</strong>。作者在 <strong>Eterna</strong> 平台上组织了一场涉及 <strong>57 个假结</strong>的竞赛，让生成式 AI 方法与有经验的人类设计者同台盲解；评价手段包括<strong>单核苷酸分辨率的化学映射、补偿性突变、以及冷冻电镜（cryo-EM）</strong>。结果显示生成式 AI 在多数盲题上与人类高手打成平手，AI 生成的分子不仅二级结构准确，还折叠成<strong>由非经典三级相互作用稳定</strong>的良好有序三维构象。这项工作由 27 位作者合作完成（含蛋白设计领域知名学者 David Baker）。</p><p>📎 DOI: <a href="https://doi.org/10.1126/science.aeg6829" target="_blank" rel="noreferrer">10.1126/science.aeg6829</a></p><h3 id="🦴-trace-不依赖参考基因组与外来群-从祖先重组图中捞出-幽灵-古人类血缘" tabindex="-1">🦴 TRACE：不依赖参考基因组与外来群，从祖先重组图中捞出&quot;幽灵&quot;古人类血缘 <a class="header-anchor" href="#🦴-trace-不依赖参考基因组与外来群-从祖先重组图中捞出-幽灵-古人类血缘" aria-label="Permalink to &quot;🦴 TRACE：不依赖参考基因组与外来群，从祖先重组图中捞出&quot;幽灵&quot;古人类血缘&quot;">​</a></h3><p><strong>Recovering signatures of archaic hominin introgression using ancestral recombination graphs</strong><em>Science（2026）</em></p><p>现代人基因组中留有已灭绝古人类（尼安德特人、丹尼索瓦人）的混血印记，但重建这段历史一直受制于<strong>古样本稀少、且缺少&quot;未混合&quot;的外来群</strong>。作者提出 <strong>TRACE</strong>：一种<strong>既不需要参考基因组、也不需要外来群</strong>的方法，改用<strong>祖先重组图（ARG）<strong>的结构特征来识别古人类血缘。模拟显示 TRACE <strong>精度高、假发现率低</strong>；应用于 <strong>1000 基因组</strong>数据时，它既复现了已知的尼安德特 / 丹尼索瓦混血信号，还</strong>在非洲人与非非洲人中同时找出未被刻画过的&quot;幽灵&quot;古人类混血</strong>，且该幽灵血缘在尼安德特人基因组中持续存在。这为新混血事件与&quot;缺失的近亲&quot;提供了无需古 DNA 的检索工具。</p><p>📎 DOI: <a href="https://doi.org/10.1126/science.aef8874" target="_blank" rel="noreferrer">10.1126/science.aef8874</a></p><h3 id="⚡-直接蒸发长出单晶金属电极-二维半导体接触瓶颈的新解法" tabindex="-1">⚡ 直接蒸发长出单晶金属电极：二维半导体接触瓶颈的新解法 <a class="header-anchor" href="#⚡-直接蒸发长出单晶金属电极-二维半导体接触瓶颈的新解法" aria-label="Permalink to &quot;⚡ 直接蒸发长出单晶金属电极：二维半导体接触瓶颈的新解法&quot;">​</a></h3><p><strong>Direct evaporation of single-crystal metal contacts for 2D semiconductors</strong><em>Science（2026）</em></p><p>金属—半导体接触是二维半导体电子学的关键瓶颈（势垒高、界面脏、接触电阻大）。作者开发了一套<strong>原子级、分步进行的蒸发方法</strong>，直接在单层半导体上生长<strong>单晶金属</strong>，得到<strong>洁净界面</strong>。其关键在于进入一个特殊的<strong>生长动力学窗口</strong>：<strong>抑制二次成核、促进横向合并</strong>，从而实现铋、银、铟、金、钯等多种金属在 <strong>MoS₂ 与 WSe₂</strong> 上的<strong>范德瓦耳斯外延</strong>。单晶金属支撑起<strong>超薄导电层</strong>，与传统多晶/无序金属接触的形貌与电学行为截然不同，为二维器件把&quot;接触&quot;从工艺难题变成可控的材料设计问题。</p><p>📎 DOI: <a href="https://doi.org/10.1126/science.aee3132" target="_blank" rel="noreferrer">10.1126/science.aee3132</a></p><h3 id="🌊-注入诱发地震-92-有前震-加拿大西部-77-条序列给出-红绿灯-新判据" tabindex="-1">🌊 注入诱发地震 92% 有前震：加拿大西部 77 条序列给出&quot;红绿灯&quot;新判据 <a class="header-anchor" href="#🌊-注入诱发地震-92-有前震-加拿大西部-77-条序列给出-红绿灯-新判据" aria-label="Permalink to &quot;🌊 注入诱发地震 92% 有前震：加拿大西部 77 条序列给出&quot;红绿灯&quot;新判据&quot;">​</a></h3><p><strong>Foreshock productivity and rupture nucleation in injection-induced earthquakes in western Canada</strong><em>Science（2026）</em></p><p>前震活动是<strong>红绿灯协议（TLP）<strong>缓解注入诱发地震（IIE）风险的关键考量，但 IIE 前震的孕震过程一直不清楚。作者用 <strong>2014–2024 年加拿大西部增强目录</strong>，统计分析了 <strong>77 条 IIE 序列</strong>在局部震级 <strong>M_L ≥ 3</strong> 主震之前的前震形态。结果显示 <strong>92% 的主震之前都有前震</strong>，且</strong>前震的产出率与时空格局</strong>反映了<strong>流体注入、孕震指数（seismogenic index）与断层应力状态</strong>三者的相互作用。逐序列分析提示：主震并非凭空出现，而是<strong>可被前震信号提前指示的成核过程</strong>，这为把前震统计纳入注入作业的风险阈值提供了观测依据。</p><p>📎 DOI: <a href="https://doi.org/10.1126/science.aed9893" target="_blank" rel="noreferrer">10.1126/science.aed9893</a></p><h3 id="🎲-给香农信息论装上-逻辑推理-压缩极限之外的另一类基本极限" tabindex="-1">🎲 给香农信息论装上&quot;逻辑推理&quot;：压缩极限之外的另一类基本极限 <a class="header-anchor" href="#🎲-给香农信息论装上-逻辑推理-压缩极限之外的另一类基本极限" aria-label="Permalink to &quot;🎲 给香农信息论装上&quot;逻辑推理&quot;：压缩极限之外的另一类基本极限&quot;">​</a></h3><p><strong>Fundamental limits incorporating logical reasoning into Shannon&#39;s information theory</strong><em>PNAS（2026）</em></p><p>香农信息论的奠基性思路是<strong>把消息的&quot;含义&quot;与&quot;高效传输&quot;解耦</strong>：来自随机源的消息，其压缩极限就是信源的熵。本文提出<strong>香农通信模型的推广</strong>：假设<strong>发送方与接收方都具备推理能力</strong>，从而把<strong>信息论与数理逻辑</strong>耦合起来。作者研究的不是&quot;消息本身&quot;，而是<strong>接收方能够从消息中推出的逻辑结论</strong>，并在此设定下刻画新的基本极限。这为&quot;语义通信 / 推理型压缩&quot;这类问题给出了可分析的框架——当双方都会推理时，&quot;传什么&quot;与&quot;能推出什么&quot;是两套不同的问题。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2525600123" target="_blank" rel="noreferrer">10.1073/pnas.2525600123</a></p><h2 id="🤖-ai-前沿" tabindex="-1">🤖 AI 前沿 <a class="header-anchor" href="#🤖-ai-前沿" aria-label="Permalink to &quot;🤖 AI 前沿&quot;">​</a></h2><h3 id="🎧-音视频-llm-的-先验支配-跨模态冲突下它们不是在组合证据-而是在念答案" tabindex="-1">🎧 音视频 LLM 的&quot;先验支配&quot;：跨模态冲突下它们不是在组合证据，而是在念答案 <a class="header-anchor" href="#🎧-音视频-llm-的-先验支配-跨模态冲突下它们不是在组合证据-而是在念答案" aria-label="Permalink to &quot;🎧 音视频 LLM 的&quot;先验支配&quot;：跨模态冲突下它们不是在组合证据，而是在念答案&quot;">​</a></h3><p><strong>Compositional Failure in Audio-Visual LLMs: Late-Layer Prior Dominance Under Cross-modal Conflict</strong><em>arXiv（2026）</em></p><p>把<strong>语义不兼容、但时间同步</strong>的音频与视频配对，是检验音视频大模型（AV-LLM）<strong>组合泛化</strong>的好测试：模型要判断这对是否匹配。结果很糟：<strong>VideoLLaMA 2-7B-AV</strong> 在 AVHBench 的精确字符串 Yes/No 子集上，三种对齐配置都<strong>接近随机</strong>；<strong>InternVideo2</strong> 在跨模态冲突下准确率下跌 <strong>32.3%</strong>，并伴随 <strong>17.3% 的指令遵循失败</strong>。作者把这种失效命名为 <strong>&quot;先验支配&quot;（prior dominance）</strong>——<strong>在网络的深夜层，模型对&quot;内部偏好的答案模式&quot;做出承诺</strong>，而这个承诺与冲突的输入证据关联很弱。机理分析显示这种承诺<strong>集中在第 25.5 ± 1 层</strong>；更强调时间对齐会<strong>改变答案偏置</strong>，但<strong>并不改善冲突消解</strong>。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.27785" target="_blank" rel="noreferrer">2608.27785</a></p><h3 id="🛠️-为什么不去查一下-工具型语言模型的-未支撑结论-与可修复性" tabindex="-1">🛠️ &quot;为什么不去查一下？&quot;：工具型语言模型的&quot;未支撑结论&quot;与可修复性 <a class="header-anchor" href="#🛠️-为什么不去查一下-工具型语言模型的-未支撑结论-与可修复性" aria-label="Permalink to &quot;🛠️ &quot;为什么不去查一下？&quot;：工具型语言模型的&quot;未支撑结论&quot;与可修复性&quot;">​</a></h3><p><strong>Why Didn&#39;t It Check? Unsupported Final Claims and Their Repair in Two Tool-Equipped Language Models</strong><em>arXiv（2026）</em></p><p>有工具可用的语言模型，仍会在<strong>证据不支持</strong>的情况下下最终结论——即使<strong>一次工具调用就能消除不确定性</strong>，且指令明确禁止猜测。作者把这个失效拆成两个可测量量：<strong>发生率</strong>（模型自发做出未支撑结论的频率，仅用可见证据与最终结论判定，不用隐藏正确答案）与<strong>条件修复率</strong>（补上缺失证据后，这些自然发生的错误是否被修正）。在固定的 <strong>Qwen3-32B</strong> 设置下，256 条新提示模板的 512 次首答中有 <strong>33 次</strong>以&quot;已确立&quot;的未支撑结论收尾；对每个案例做<strong>状态精确复现的配对重放</strong>（两种工具响应的结构、长度完全相同，只差一个字符的响应码），<strong>有效证据修复了 33/33</strong>，而<strong>无信息响应修复 0/33</strong>；当证据原本支持原答案时，<strong>33/33 被保留、未观察到损害</strong>。另一组实验中，一条<strong>自动检查规则</strong>对 64 个需要证据的案例追加了 21 次证据调用，<strong>纠正了全部 10 个错误结论、保留了 11 个&quot;碰巧正确&quot;的结论、且从未把正确答案改错</strong>。同样的采样设置下 <strong>Gemma 4</strong> 也呈现同类模式。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.27768" target="_blank" rel="noreferrer">2608.27768</a></p><h3 id="♟️-不做搜索的国际象棋-用-先验导向探索-替代熵奖励-棋力与题力竟会分家" tabindex="-1">♟️ 不做搜索的国际象棋：用&quot;先验导向探索&quot;替代熵奖励，棋力与题力竟会分家 <a class="header-anchor" href="#♟️-不做搜索的国际象棋-用-先验导向探索-替代熵奖励-棋力与题力竟会分家" aria-label="Permalink to &quot;♟️ 不做搜索的国际象棋：用&quot;先验导向探索&quot;替代熵奖励，棋力与题力竟会分家&quot;">​</a></h3><p><strong>Beyond Search-Imitation: Prior-Directed Exploration for Searchless Chess</strong><em>arXiv（2026）</em></p><p>无搜索棋网靠<strong>单次前向</strong>达到人类大师水平，但它是在<strong>模仿搜索</strong>——蒸馏 AlphaZero 式 MCTS 的访问计数（最强的开源模型是 Leela Chess Zero 的 Chessformer）。模仿搜索并不等于会下无搜索的棋，于是作者用<strong>自对弈强化学习</strong>直接优化单次前向的棋力。关键改动是把常用的熵奖励（趋向均匀分布的反向 KL）换成<strong>朝网络自身 MCTS 先验的、质量覆盖型的前向 KL</strong>——让探索集中在先验认为有希望的着法；再配一个<strong>由价值头结果不确定性驱动、局面已定时自动变锐的熵自适应采样温度</strong>。约 <strong>2000 步</strong>内，10 万题题库的<strong>解题准确率 93.9% → 94.9%</strong>、<strong>四步杀 77% → 81%</strong>，同时无搜索棋力<strong>持平或略高于基线</strong>。在匹配算力的扫描中，<strong>战术准确率与棋力出现解耦</strong>：准确率提升落在 1 个百分点带内，而等级分跨在基线两侧；只微调题目的对照组取得<strong>本研究最大的战术提升，却掉了约 260 Elo</strong>——&quot;更好的解题者&quot;未必是&quot;更强的棋手&quot;。分布层面的测量显示，<strong>没有正则项时自对弈会坍缩</strong>，这正是&quot;锚定&quot;买到的东西。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.27757" target="_blank" rel="noreferrer">2608.27757</a></p><h3 id="🔐-若智能体皆是天使-就不需要治理-把策略执法挪到可信工具边界之外" tabindex="-1">🔐 &quot;若智能体皆是天使，就不需要治理&quot;：把策略执法挪到可信工具边界之外 <a class="header-anchor" href="#🔐-若智能体皆是天使-就不需要治理-把策略执法挪到可信工具边界之外" aria-label="Permalink to &quot;🔐 &quot;若智能体皆是天使，就不需要治理&quot;：把策略执法挪到可信工具边界之外&quot;">​</a></h3><p><strong>If Agents Were Angels, No Governance Would Be Necessary: Out-of-Band Policy Enforcement at a Trusted Tool Boundary</strong><em>arXiv（2026）</em></p><p>把人的凭据交给智能体，它就<strong>继承了人的权限范围、却没有人的判断力</strong>：它可以把所有可达记录扫进模型上下文，其中的隐藏指令再操纵它的下一次调用，而<strong>每个请求在凭据上始终合法</strong>。提示词是脆弱的护栏（终究要靠&quot;一个有缺陷的推理者&quot;来解释并执行限制）。作者提出 <strong>OBPE（Out-of-Band Policy Enforcement）</strong>：在<strong>智能体推理之外</strong>设置一个可信边界，负责<strong>授权带类型的操作与资源</strong>、在调用后端前<strong>收窄查询</strong>、再对响应<strong>做记录/字段过滤或取值掩码</strong>；<strong>语义门控</strong>可依据参数取值或外部状态拒绝/暂扣一个已授权的调用。<strong>数据策略所有者设定授权上限，智能体策略只能收窄、不能放宽</strong>，并在给定条件下证明了策略计划<strong>与顺序无关</strong>。作者发布了一个从生产系统简化而来的 HTTP 代理原型，其类型化 <strong>Cedar</strong> 策略内核与模型之间有一致性测试。在 Jira 与 ServiceNow 模拟环境、4 个模型（含 20 项自适应红队任务）共 <strong>3,621 次试验</strong>中，&quot;受保护数据进入智能体上下文 / 精确取值出现在答案里 / 发生被禁止的副作用&quot;这类<strong>轨迹失败从 57.6% 降到 0.2%</strong>。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.27646" target="_blank" rel="noreferrer">2608.27646</a></p><h3 id="📚-wikiskill-把智能体的执行经验-编译-进持久知识库-让技能持续进化" tabindex="-1">📚 WikiSkill：把智能体的执行经验&quot;编译&quot;进持久知识库，让技能持续进化 <a class="header-anchor" href="#📚-wikiskill-把智能体的执行经验-编译-进持久知识库-让技能持续进化" aria-label="Permalink to &quot;📚 WikiSkill：把智能体的执行经验&quot;编译&quot;进持久知识库，让技能持续进化&quot;">​</a></h3><p><strong>WikiSkill: Compiling Agent Experience into Persistent Knowledge for Skill Evolution</strong><em>arXiv（2026）</em></p><p>&quot;智能体技能&quot;把专门知识与工作流打包成可复用资源，近期工作已能从执行经验里<strong>自动发现技能</strong>；但<strong>指导技能演化的洞见往往散落在各次优化历史里</strong>，难以被系统化复用。<strong>WikiSkill</strong> 提出让<strong>技能与持久知识库（wiki）共同演化</strong>：显式区分<strong>原始执行经验、累积知识、可执行技能</strong>三者，并<strong>持续把经验整合进 wiki</strong>，供后续技能更新在其上建设。在多个基准与模型上，它稳定优于当前最先进的技能演化方法，并在大多数&quot;模型×基准&quot;组合上优于无技能基线。两个关键发现：<strong>技能演化与模型规模互补</strong>（更大的模型通常从演化出的技能里获益更多，而<strong>带技能的小模型可以显著超过没有技能的大模型</strong>）；<strong>演化出的技能可跨模型与模型家族迁移</strong>，且<strong>别的模型演化出的技能可能胜过自己演化的</strong>。消融实验确认：<strong>wiki 中持久的知识积累是技能有效演化的关键</strong>。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.27454" target="_blank" rel="noreferrer">2608.27454</a></p><blockquote><p>📅 日期：2026-08-27 ｜ ⚠️ 事后重建版 ｜ 📂 科学前沿 5 篇 | 🤖 AI前沿 5 篇</p></blockquote>',45)])])}const p=r(e,[["render",a]]);export{q as __pageData,p as default};
